    jest.spyOn(Color, "_isValidSpace").mockReturnValue(true);
    jest.spyOn(Color, "_getCorrectColor").mockImplementation((colorArray) => colorArray);
    const result = colorInstance.convert(["RGB", 1, 0, 0], "RGB");
